from __future__ import annotations
import logging

from taf.internal.aliasing import aliasing_scope
from taf.internal.robot_typecasts import time_to_seconds, to_boolean

from .facade import SyslogInstance


class syslog:
    """
    Enables collecting and parsing syslog messages from remote/local machine.

    How it works
    ************

    Start Syslog keyword connects via SSH to a remote or local machine and executes script
    found in "taf/sw/syslog/__main__.py" which in turn start UDP Listeners on specified ports,
    and a Logger instance which writes incoming messages to a file or files.
    """

    ROBOT_LIBRARY_SCOPE = "TEST SUITE"

    # To provide backwards compatibility lookup argument must remain as "alias"
    # In order to keep the code readable, after the lookup it will be assigned
    # to `syslog` variable in every method
    lookup_handler, store = aliasing_scope(
        name=__name__, lookup_arg="alias", lookup_type=SyslogInstance
    )
    _logger = logging.getLogger(__name__)

    def start_syslog(
        self,
        log_dir: str,
        log_name: str,
        ip: str = "",
        ports: tuple[int] | int = (51000, 51001, 51003, 50011),
        host_ip: str = "127.0.0.1",
        file_limit: int = 0,
        add_line_number: bool = False,
        virtualenv_dir: str | None = None,
        alias: str | None = None,
        ssh_username: str = "ute",
        ssh_password: str = "ute",
        ssh_port: int = 22,
        cli_prefix: str | None = None,
        temp_dir: str = "/tmp",
    ) -> None:
        r"""
        Start collecting syslog.

        The library will look for ``cli_syslog`` in the following order:

        #. If you have specified ``virtualenv_dir``, it will look in this environment only. This also takes a pyenv
           venv NAME into account, e.g., ``test_repo``
        #. Else it will try to look for the command in the base environment
        #. If the command is not found in the base environment, it will check whether ``pyenv`` is available in
           ``$HOME/.pyenv/bin/pyenv`` and if it is, look for ``cli_syslog`` with pyenv activated

        If ``cli_syslog`` is not found ,``SyslogCLINotFoundError`` will be raised.

        :param str                  log_dir:        Path to directory where syslog file should be stored.
        :param str                  log_name:       Name of file where collected data should be stored during collection.
        :param str, optional        ip:             Custom IP address service should listen, e.g., 192.168.255.126.
                                                    default all addresses and all interfaces (0.0.0.0/0).
        :param tuple[int], optional ports:          Single or List of ports which will be used to collect syslog data.
                                                    Default is ``(51000, 51001, 51003, 50011)``
        :param str, optional        host_ip:        IP Address of remote/local machine. Defaults to ``127.0.0.1``
        :param int, optional        file_limit:     Size limit for the log file. Log file will be split into smaller parts if configured
                                                    size is greater than 0. Size limit is specified in bytes. Defaults to 0
        :param bool, optional       add_line_number:    Add line numbers to the generated log file. Defaults to ``False``
        :param str, optional        virtualenv_dir: Use particular virtualenv when connecting to the host. If using localhost,
                                                    by default this will try to use the current one.
        :param str, optional        alias:          Unique identifier for a certain syslog instance. Default is ``None``.
        :param str, optional        ssh_username:   Username for SSH authentication. Default is ``ute``.
        :param str, optional        ssh_password:   Password for SSH authentication. Default is ``ute``.
        :param int, optional        ssh_port:       SSH service port on specified machine. Default is 22.
        :param str, optional        cli_prefix:     Prefix which will allow wrapping cli_syslog with another command or pass environment variables.
        :param str, optional        temp_dir:       Allows to override the default ``/tmp``
        """
        if host_ip is None:
            raise ValueError(
                "host_ip argument cannot be None! "
                "If you want to use default value '127.0.0.1', simply don't pass this argument"
            )

        ssh_params_dict = {
            "ssh_ip": host_ip,
            "ssh_username": ssh_username,
            "ssh_password": ssh_password,
            "ssh_port": ssh_port,
        }
        syslog = SyslogInstance(
            log_dir=log_dir,
            log_name=log_name,
            host_ip=host_ip,
            ip=ip,
            ports=ports,
            file_limit=file_limit,
            add_line_number=to_boolean(add_line_number),
            virtualenv_dir=virtualenv_dir,
            cli_prefix=cli_prefix,
            temp_dir=temp_dir,
        )
        syslog.setup(ssh_params_dict)
        syslog.start()
        self.store.add(syslog, alias)

    @lookup_handler.implicit_lookup
    def count_syslog_messages(self, regexp: str, alias: str = None) -> int:
        """Count how many messages have been collected up to this point.

        :param str              regexp: Pattern used to find the message in the syslog file.
        :param str, optional    alias:  Unique identifier for a certain syslog instance. Default is ``None``.
        :raises: WrongResponseError
        :return int: Number of found messages
        """
        syslog: SyslogInstance = alias
        return syslog.count_syslog_messages(regexp=regexp)

    @lookup_handler.implicit_lookup
    def message_should_exist_in_syslog_file(
        self, regexp: str, alias: str | None = None, savepoint: str | None = None
    ) -> str:
        """Check if a message exists in a file created by the syslog service.

        :param str              regexp:       Python regexp needed to perform the search operation.
        :param str, optional    alias:        Alias of the syslog instance
        :param str, optional    savepoint:    Savepoint to start searching from.
        :return str: Found message.
        :raises: ParsingError when regexp cannot match any string
        :note: Character ``\\`` has to be additionally escaped because it is interpreted by the Robot Framework, e.g \\s has to be \\s.
        """
        syslog: SyslogInstance = alias

        if savepoint:
            return syslog.message_should_exist_from_savepoint(regexp, savepoint)
        else:
            return syslog.message_should_exist(regexp)

    @lookup_handler.implicit_lookup
    def wait_for_message_in_syslog_file(
        self, regexp: str, timeout: str | int, alias=None
    ) -> str:
        """Wait for a message to appear in the syslog file.

        :param str              regexp:     Python regexp needed to perform the search operation, see :ref:`regexp`.
        :param int|str          timeout:    Timeout in seconds or as a Robot time string.
        :param str, optional    alias:      Alias of the syslog instance.

        :return str: Found message
        :raises: ParsingError when regexp cannot match any string

        :note: Character ``\\`` has to be additionally escaped because it is interpreted by the Robot Framework, e.g \\s has to be \\s.
        """
        syslog: SyslogInstance = alias
        return syslog.wait_for_message(regexp, timeout=time_to_seconds(timeout))

    @lookup_handler.implicit_lookup
    def stop_syslog(self, alias: str | None = None) -> None:
        """Stop syslog instance.

        :param str, optional alias: Unique identifier for a certain syslog instance. Default is ``None``.
        """
        syslog: SyslogInstance = alias
        syslog.stop_syslog_and_cleanup()
        self._teardown_syslog(syslog_instance=syslog)

    @lookup_handler.implicit_lookup
    def collect_syslog_results(
        self, destination: str | None = None, unzip: str | bool = True, alias: str | None = None
    ) -> None:
        """Stop syslog and download the created file to the destination path.

        Download .tar.gz file to the destination path and extract it if unzip is set to True.
        Destination parameter must be aligned with unzip parameter:

        - if unzip is true, then the destination must be a path of a directory
            ``syslog.collect_syslog_results(destination='/tmp/syslog_files', unzip=True)``
        - if unzip is False, the destination must be a path to a file ending with ".tar.gz"
            ``syslog.collect_syslog_results(destination='/tmp/syslog_files/syslog.tar.gz', unzip=False)``

        :param str, optional     destination:   Path of a directory or filename that the file should be downloaded to, Defaults to
                                                ``{log_dir}/{log_name}`` from start_syslog KW, so the same directory where the logs are stored.
        :param bool, optional    unzip:         Flag indicating whether downloaded logs should be extracted after collection. Defaults to ``True``
        :param str, optional     alias:         Unique identifier for a certain syslog instance. Default is ``None``.
        :raises FileCollectorError:
        """
        syslog: SyslogInstance = alias
        syslog.collect_syslog_results(destination, to_boolean(unzip))
        self._teardown_syslog(syslog_instance=syslog)

    def teardown_all_aliases_for_syslog(self) -> None:
        """Stop all syslog instances and then collect the logs generated by all aliases."""
        aliases = [alias_name for alias_name, _ in self.store.all]
        for alias in aliases:
            self.collect_syslog_results(alias=alias)

    @lookup_handler.implicit_lookup
    def capture_savepoint(self, alias: str | None = None) -> str:
        """Capture the timestamp of last log.

        :param str, optional alias: Unique identifier for a certain syslog instance. Defaults to ``None``

        :return: Timestamp string of the last line in syslog file.
        """
        syslog: SyslogInstance = alias
        return syslog.capture_savepoint()

    @lookup_handler.implicit_lookup
    def collect_from_savepoint(
        self,
        savepoint: str,
        destination_file: str,
        file_limit: int = 0,
        compress: bool = False,
        alias: str | None = None,
    ) -> None:
        """Collect logs starting from savepoint until the current saved logs.

        :param str              savepoint:          Timestamp that will indicate where to start the search
        :param str              destination_file:   File path where the logs will be stored
        :param int,  optional   file_limit:         Value in bytes (minimum 1000) to limit the size when splitting log files. Default is 0 and means
                                                    that the file will not be split
        :param bool, optional   compress:           Flag for setting if the collected logs should be compressed to tar.gz. Default is ``False``
        :param str,  optional   alias:              Unique identifier for a certain syslog instance. Default is ``None``.
        """
        syslog: SyslogInstance = alias
        syslog.collect_from_savepoint(
            savepoint, destination_file, file_limit, to_boolean(compress)
        )

    def _teardown_syslog(self, syslog_instance: SyslogInstance) -> None:
        """Clean up information set by start_syslog keyword and stop working syslog."""
        self.store.remove_object(syslog_instance)
